// Evaluates the count of historical matches found in the database
if ($historical_matches > 1) {
    return `RISK DETECTED: Duplicate Invoice! Invoice No ${$invoice_no} for Vendor ${$vendor_id} already appears ${$historical_matches} times in the system.`;
} else if ($historical_matches === 1) {
    return "PASS: This is a unique, first-time invoice submission.";
} else {
    // Must return a string
    return "PASS: No previous record of this invoice exists.";
}
